    fbb_.Required(o, GEL::VT_PROVENANCE);
    fbb_.Required(o, GEL::VT_PRODUCER_ID);
    fbb_.Required(o, GEL::VT_SIGNATURE);
    fbb_.Required(o, GEL::VT_CANONICAL_JSON_SIGNATURE);
