inline ::flatbuffers::Offset<GEL> CreateGEL(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> GEL_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> NAME = 0,
    ::flatbuffers::Offset<::flatbuffers::String> SCENARIO_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> EMITTER_ID = 0,
    gelTechniqueClass TECHNIQUE = gelTechniqueClass_UNSPECIFIED,
    double SOLUTION_EPOCH = 0.0,
    double LATITUDE_DEG = 0.0,
    double LONGITUDE_DEG = 0.0,
    double ALTITUDE_M = 0.0,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> ENU_COVARIANCE_M2 = 0,
    double ERROR_ELLIPSE_SEMI_MAJOR_M = 0.0,
    double ERROR_ELLIPSE_SEMI_MINOR_M = 0.0,
    double ERROR_ELLIPSE_ORIENTATION_DEG = 0.0,
    double CEP50_M = 0.0,
    double CEP95_M = 0.0,
    double GDOP = 0.0,
    double VELOCITY_EAST_M_S = 0.0,
    double VELOCITY_NORTH_M_S = 0.0,
    double VELOCITY_UP_M_S = 0.0,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> VELOCITY_COVARIANCE_M2_S2 = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<GELObservationRef>>> OBSERVATION_REFS = 0,
    ::flatbuffers::Offset<GELConvergenceDiagnostics> CONVERGENCE_DIAGNOSTICS = 0,
    ::flatbuffers::Offset<RFLProvenance> PROVENANCE = 0,
    uint64_t COMPUTED_AT = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PRODUCER_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint8_t>> SIGNATURE = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<uint8_t>> CANONICAL_JSON_SIGNATURE = 0) {
  GELBuilder builder_(_fbb);
  builder_.add_COMPUTED_AT(COMPUTED_AT);
  builder_.add_VELOCITY_UP_M_S(VELOCITY_UP_M_S);
  builder_.add_VELOCITY_NORTH_M_S(VELOCITY_NORTH_M_S);
  builder_.add_VELOCITY_EAST_M_S(VELOCITY_EAST_M_S);
  builder_.add_GDOP(GDOP);
  builder_.add_CEP95_M(CEP95_M);
  builder_.add_CEP50_M(CEP50_M);
  builder_.add_ERROR_ELLIPSE_ORIENTATION_DEG(ERROR_ELLIPSE_ORIENTATION_DEG);
  builder_.add_ERROR_ELLIPSE_SEMI_MINOR_M(ERROR_ELLIPSE_SEMI_MINOR_M);
  builder_.add_ERROR_ELLIPSE_SEMI_MAJOR_M(ERROR_ELLIPSE_SEMI_MAJOR_M);
  builder_.add_ALTITUDE_M(ALTITUDE_M);
  builder_.add_LONGITUDE_DEG(LONGITUDE_DEG);
  builder_.add_LATITUDE_DEG(LATITUDE_DEG);
  builder_.add_SOLUTION_EPOCH(SOLUTION_EPOCH);
  builder_.add_CANONICAL_JSON_SIGNATURE(CANONICAL_JSON_SIGNATURE);
  builder_.add_SIGNATURE(SIGNATURE);
  builder_.add_PRODUCER_ID(PRODUCER_ID);
  builder_.add_PROVENANCE(PROVENANCE);
  builder_.add_CONVERGENCE_DIAGNOSTICS(CONVERGENCE_DIAGNOSTICS);
  builder_.add_OBSERVATION_REFS(OBSERVATION_REFS);
  builder_.add_VELOCITY_COVARIANCE_M2_S2(VELOCITY_COVARIANCE_M2_S2);
  builder_.add_ENU_COVARIANCE_M2(ENU_COVARIANCE_M2);
  builder_.add_EMITTER_ID(EMITTER_ID);
  builder_.add_SCENARIO_ID(SCENARIO_ID);
  builder_.add_NAME(NAME);
  builder_.add_GEL_ID(GEL_ID);
  builder_.add_TECHNIQUE(TECHNIQUE);
  return builder_.Finish();
}

