  auto OBSERVATION_REFS__ = OBSERVATION_REFS ? _fbb.CreateVector<::flatbuffers::Offset<GELObservationRef>>(*OBSERVATION_REFS) : 0;
  auto PRODUCER_ID__ = PRODUCER_ID ? _fbb.CreateString(PRODUCER_ID) : 0;
