inline const GEL *GetGEL(const void *buf) {
  return ::flatbuffers::GetRoot<GEL>(buf);
}

inline const GEL *GetSizePrefixedGEL(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<GEL>(buf);
}

inline const char *GELIdentifier() {
  return "$GEL";
}

inline bool GELBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GELIdentifier());
}

inline bool SizePrefixedGELBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GELIdentifier(), true);
}

template <bool B = false>
inline bool VerifyGELBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<GEL>(GELIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedGELBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<GEL>(GELIdentifier());
}

inline void FinishGELBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GEL> root) {
  fbb.Finish(root, GELIdentifier());
}

inline void FinishSizePrefixedGELBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GEL> root) {
  fbb.FinishSizePrefixed(root, GELIdentifier());
}

